statement:
You are given four integers `minLength`, `maxLength`, `oneGroup` and `zeroGroup`. A binary string (made of the characters `0` and `1`) is **good** when all of these hold:

- its length is at least `minLength` and at most `maxLength`;
- every maximal run of consecutive `1`s has a length that is a multiple of `oneGroup`;
- every maximal run of consecutive `0`s has a length that is a multiple of `zeroGroup`.

A string with no `1`s (or no `0`s) at all is fine, since 0 counts as a multiple of every number. Return how many good binary strings exist, modulo `10^9 + 7`.

validator:
function validate([minLength, maxLength, oneGroup, zeroGroup]) {
  if (![minLength, maxLength, oneGroup, zeroGroup].every(Number.isInteger)) return 'All four values are integers.';
  if (minLength < 1 || maxLength > 100000 || minLength > maxLength) return 'Need 1 <= minLength <= maxLength <= 10^5.';
  if (oneGroup < 1 || oneGroup > maxLength) return 'oneGroup is between 1 and maxLength.';
  if (zeroGroup < 1 || zeroGroup > maxLength) return 'zeroGroup is between 1 and maxLength.';
  return null;
}

reference:
function goodBinaryStrings(minLength, maxLength, oneGroup, zeroGroup) {
  const MOD = 1000000007;
  const dp = new Array(maxLength + 1).fill(0);
  dp[0] = 1;
  let count = 0;

  for (let length = 1; length <= maxLength; length++) {
    if (length >= oneGroup) {
      dp[length] = (dp[length] + dp[length - oneGroup]) % MOD;
    }
    if (length >= zeroGroup) {
      dp[length] = (dp[length] + dp[length - zeroGroup]) % MOD;
    }
    if (length >= minLength) {
      count = (count + dp[length]) % MOD;
    }
  }
  return count;
}

brute:
function goodBinaryStrings(minLength, maxLength, oneGroup, zeroGroup) {
  // List every binary string of an allowed length and test its runs directly.
  let total = 0;
  for (let len = minLength; len <= maxLength; len++) {
    for (let mask = 0; mask < (1 << len); mask++) {
      const text = mask.toString(2).padStart(len, '0');
      const runs = text.match(/0+|1+/g);
      const good = runs.every(run => run.length % (run[0] === '1' ? oneGroup : zeroGroup) === 0);
      if (good) total++;
    }
  }
  return total % 1000000007;
}

