function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const maxLength = pick(50000, 100000);
    const minLength = rand() < 0.3 ? 1 : pick(1, maxLength);
    // Small groups give huge counts that exercise the modulus; occasionally a group is large.
    const group = () => (rand() < 0.8 ? pick(1, 12) : pick(1, maxLength));
    return [minLength, maxLength, group(), group()];
  }
  const maxLength = pick(1, 12);
  const minLength = pick(1, maxLength);
  const group = () => (rand() < 0.6 ? pick(1, Math.min(4, maxLength)) : pick(1, maxLength));
  return [minLength, maxLength, group(), group()];
}
